	testCases := map[string]bool{
		".*-.*-.*-.*-.*": true,
		".+-.*-.*-.*-.+": false,
		"-.*-.*-.*-.*":   false,
		".*-.*-.*-.*-":   false,
		"-":              false,
		".*":             false,
		`.*\|foo\|.*`:    true,
