// durationLiteralOutOfRange reports whether val, interpreted as seconds, would
// overflow a time.Duration (int64 nanoseconds).
func durationLiteralOutOfRange(val float64) bool {
	return val > 1<<63/1e9 || val < -(1<<63)/1e9
}

