    use crate::schema::users::table as users;
    let connection = &mut connection();
    diesel::sql_query(
        "CREATE TEMPORARY TABLE users (
        id SERIAL PRIMARY KEY,
        name VARCHAR(50) NOT NULL,
        hair_color VARCHAR(10) NOT NULL DEFAULT 'Green'
    )",
